export const pensionFundsData: PensionFund[] = allRows.map((row): PensionFund => {
  const [
    type, nAlbo, fondo, societa, comparto, categoria,
    ultimoAnno, ultimi3Anni, ultimi5Anni, ultimi10Anni, ultimi20Anni,
    isc2a, isc5a, isc10a, isc35a, categoriaContratto, sitoWeb,
    categoriaEstesa, classificazioneCovip, garanzia, costoAdesione, costoAnnuoGestione,
    costoGestioneFinanziaria, costoAnticipazione, costoTrasferimento, costoRiscatto,
    costoRiallocazionePosizione, costoRiallocazioneFlusso, costoErogazione, benchmark,
    azionario, obbligazionario, dataInizioQuotazione, sostenibilita, sourceRating,
    chiusoNuoviAderenti, hasCollectiveAgreements, collectiveAgreementLabel,
    subscriptionCostIndividual, subscriptionCostCollective, collectiveManagementFee, incentiveFee,
    collectiveAgreementNotes, collectiveAgreementSource
  ] = row;

  const isc5aValue = parseFloatOrNull(isc5a);
  const fundWithoutRating: Omit<PensionFund, 'rating'> = {
    id: generateId(type, nAlbo, comparto),
    type: type as FundType,
    societa: emptyToNull(societa),
    pip: fondo,
    nAlbo: Number.parseInt(nAlbo, 10),
    linea: comparto,
    ramo: null,
    categoria: categoria as FundCategory,
    categoriaEstesa: emptyToNull(categoriaEstesa),
    classificazioneCovip: emptyToNull(classificazioneCovip),
    garanzia: parseBooleanOrNull(garanzia),
    isc: {
      isc2a: parseFloatOrNull(isc2a),
      isc5a: isc5aValue,
      isc10a: parseFloatOrNull(isc10a),
      isc35a: parseFloatOrNull(isc35a),
    },
    costoAnnuo: isc5aValue,
    rendimenti: {
      ultimoAnno: parseFloatOrNull(ultimoAnno),
      ultimi3Anni: parseFloatOrNull(ultimi3Anni),
      ultimi5Anni: parseFloatOrNull(ultimi5Anni),
      ultimi10Anni: parseFloatOrNull(ultimi10Anni),
      ultimi20Anni: parseFloatOrNull(ultimi20Anni),
    },
    categoriaContratto: emptyToNull(categoriaContratto),
    sitoWeb: emptyToNull(sitoWeb),
    notaInformativa: getFundInformativeNote(type as FundType, Number.parseInt(nAlbo, 10)),
    costiDettaglio: {
      adesione: emptyToNull(costoAdesione),
      annuiGestione: emptyToNull(costoAnnuoGestione),
      gestioneFinanziaria: emptyToNull(costoGestioneFinanziaria),
      anticipazione: emptyToNull(costoAnticipazione),
      trasferimento: emptyToNull(costoTrasferimento),
      riscatto: emptyToNull(costoRiscatto),
      riallocazionePosizione: emptyToNull(costoRiallocazionePosizione),
      riallocazioneFlussoContributivo: emptyToNull(costoRiallocazioneFlusso),
      erogazione: emptyToNull(costoErogazione),
    },
    benchmark: emptyToNull(benchmark),
    assetAllocation: {
      azionario: emptyToNull(azionario),
      obbligazionario: emptyToNull(obbligazionario),
    },
    dataInizioQuotazione: emptyToNull(dataInizioQuotazione),
    sostenibilita: emptyToNull(sostenibilita),
    sourceRating: parseSourceRating(sourceRating),
    chiusoNuoviAderenti: chiusoNuoviAderenti === 'true',
    collectiveAgreementInfo: buildCollectiveAgreementInfo(
      hasCollectiveAgreements,
      collectiveAgreementLabel,
      subscriptionCostIndividual,
      subscriptionCostCollective,
      collectiveManagementFee,
      incentiveFee,
      collectiveAgreementNotes,
      collectiveAgreementSource
    ),
  };

  return { ...fundWithoutRating, rating: calculateFundRating(fundWithoutRating) };
});
